// Native test harness for the SH-WS03 interval lambda (generated by ESPHome).
// Run through tests/run_tests.sh, which generates lambda_body.inc.
// Scenario 1: normal wake. Scenario 2 (argv): line noise, time, signal, record report, no HA, pairing.
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <deque>
#include <string>
#include <vector>
#include <algorithm>

static uint32_t g_now = 0;
uint32_t millis() { return g_now; }

#define ESP_LOGD(tag, fmt, ...) std::printf("%6u [D][%s] " fmt "\n", g_now, tag, ##__VA_ARGS__)
#define ESP_LOGI(tag, fmt, ...) std::printf("%6u [I][%s] " fmt "\n", g_now, tag, ##__VA_ARGS__)
#define ESP_LOGW(tag, fmt, ...) std::printf("%6u [W][%s] " fmt "\n", g_now, tag, ##__VA_ARGS__)

std::string format_hex_pretty(const std::vector<uint8_t> &d, char sep = '.', bool show_length = true) {
  std::string s; char b[4];
  for (size_t i = 0; i < d.size(); i++) { std::snprintf(b, sizeof b, "%02X", d[i]); if (i) s += sep; s += b; }
  if (show_length) s += " (" + std::to_string(d.size()) + ")";
  return s;
}

struct UART {
  std::deque<uint8_t> rx; std::vector<std::vector<uint8_t>> tx;
  size_t available() { return rx.size(); }
  bool read_byte(uint8_t *b) { if (rx.empty()) return false; *b = rx.front(); rx.pop_front(); return true; }
  void write_array(const std::vector<uint8_t> &d) { tx.push_back(d); }
};
struct BinSensor { const char *n; int state = -1; void publish_state(bool s) { state = s; std::printf("%6u  >> %s = %s\n", g_now, n, s ? "ON" : "OFF"); } };
struct Sensor { const char *n; void publish_state(float s) { std::printf("%6u  >> %s = %.0f\n", g_now, n, s); } };
struct TextSensor { const char *n; std::string state{};
  void publish_state(const std::string &s) { state = s; std::printf("%6u  >> %s = %s\n", g_now, n, s.c_str()); }
  void publish_state(const char *s) { publish_state(std::string(s)); } };
struct ESPTime { uint8_t second, minute, hour, day_of_week, day_of_month; uint16_t day_of_year; uint8_t month; uint16_t year;
  bool is_valid() const { return year >= 2019; } };
struct Time { ESPTime now() { return ESPTime{5, 9, 16, 2, 2, 306, 11, 2026}; } };  // Mon 2026-11-02 16:09:05
struct Sleeper { int calls = 0; void begin_sleep(bool m) { calls++; std::printf("%6u  >> begin_sleep(%d)\n", g_now, m); } };
namespace wifi { struct W { bool c = false; bool is_connected() const { return c; } int8_t wifi_rssi() { return -60; } }; W *global_wifi_component; }
namespace api { struct A { bool c = false; bool is_connected() const { return c; } }; A *global_api_server; }

UART U; BinSensor S_smoke{"smoke"}, S_fault{"fault"}, S_batlow{"battery_low"}; Sensor S_pct{"battery_percent"};
TextSensor T_lvl{"battery_level"}, T_last{"last_report"}, T_prod{"mcu_product"}; Time TT; Sleeper SL;
UART *mcu_uart = &U; BinSensor *smoke = &S_smoke, *fault = &S_fault, *battery_low = &S_batlow; Sensor *battery_percent = &S_pct;
TextSensor *battery_level = &T_lvl, *last_report = &T_last, *mcu_product = &T_prod; Time *ha_time = &TT; Sleeper *sleeper = &SL;

void tick() {
#include "lambda_body.inc"
}

static void mcu_send(std::vector<uint8_t> f) {
  uint8_t cs = 0; for (auto b : f) cs += b; f.push_back(cs);
  for (auto b : f) U.rx.push_back(b);
}
static std::vector<uint8_t> frame(uint8_t cmd, std::vector<uint8_t> data) {
  std::vector<uint8_t> f = {0x55, 0xAA, 0x00, cmd, (uint8_t)(data.size() >> 8), (uint8_t)data.size()};
  f.insert(f.end(), data.begin(), data.end()); uint8_t cs = 0; for (auto b : f) cs += b; f.push_back(cs); return f;
}
static size_t seen = 0;
static void dump_tx() { for (; seen < U.tx.size(); seen++) std::printf("%6u  TX %s\n", g_now, format_hex_pretty(U.tx[seen]).c_str()); }
static bool tx_has(const std::vector<uint8_t> &f) { return std::find(U.tx.begin(), U.tx.end(), f) != U.tx.end(); }

int fails = 0;
#define CHECK(c, msg) do { if (c) std::printf("PASS %s\n", msg); else { std::printf("FAIL %s\n", msg); fails++; } } while (0)

int scenario2();
int main(int argc, char **argv) {
  if (argc > 1) return scenario2();
  wifi::W w; api::A a; wifi::global_wifi_component = &w; api::global_api_server = &a;
  auto run = [&](uint32_t until) { while (g_now < until) { tick(); dump_tx(); g_now += 20; } };

  run(100);
  CHECK(tx_has({0x55,0xAA,0x00,0x01,0x00,0x00,0x00}), "product query sent with spec frame 55 AA 00 01 00 00 00");
  std::string pj = "{\"p\":\"abc\",\"v\":\"1.0.0\"}";
  std::vector<uint8_t> pd(pj.begin(), pj.end()); mcu_send({0x55,0xAA,0x00,0x01,0x00,(uint8_t)pd.size()}); U.rx.pop_back();
  { auto f = frame(0x01, pd); U.rx.clear(); for (auto b : f) U.rx.push_back(b); }
  run(200);
  CHECK(T_prod.state == pj, "product info parsed");
  size_t q = std::count(U.tx.begin(), U.tx.end(), frame(0x01, {}));
  run(3000);
  CHECK(std::count(U.tx.begin(), U.tx.end(), frame(0x01, {})) == (long) q, "no more product queries after reply");

  w.c = true; run(3100);
  CHECK(tx_has({0x55,0xAA,0x00,0x02,0x00,0x01,0x03,0x05}), "status 03 sent when Wi-Fi up");
  for (auto b : frame(0x02, {})) U.rx.push_back(b);   // MCU ack: 55 AA 00 02 00 00 01
  run(3200);
  a.c = true; run(3300);
  CHECK(tx_has({0x55,0xAA,0x00,0x02,0x00,0x01,0x04,0x06}), "status 04 sent when API up (matches spec example)");
  for (auto b : frame(0x02, {})) U.rx.push_back(b);
  run(3400);
  size_t before = U.tx.size(); run(6000);
  CHECK(U.tx.size() == before, "no status resend after MCU ack");
  CHECK(SL.calls == 0, "no sleep before any report");

  // MCU reports: dp1 enum 0 (alarm), dp14 enum 2, dp15 value 100, dp11 bitmap 0, in one 0x05 frame
  mcu_send({0x55,0xAA,0x00,0x05,0x00,0x1C, 0x01,0x04,0x00,0x01,0x00, 0x0E,0x04,0x00,0x01,0x02,
            0x0F,0x02,0x00,0x04,0x00,0x00,0x00,0x64, 0x0B,0x05,0x00,0x01,0x00, 0x10,0x01,0x00,0x01,0x00});
  uint32_t t_rep = g_now; run(t_rep + 280);
  CHECK(!tx_has({0x55,0xAA,0x00,0x05,0x00,0x01,0x00,0x05}), "ack not sent before 300 ms");
  run(t_rep + 360);
  CHECK(tx_has({0x55,0xAA,0x00,0x05,0x00,0x01,0x00,0x05}), "0x05 ack 55 AA 00 05 00 01 00 05 after delay");
  CHECK(S_smoke.state == 1, "smoke ON for dp1=0 (Tuya standard alarm)");
  CHECK(S_fault.state == 0, "fault OFF for dp11=0");
  CHECK(S_batlow.state == 0 && T_lvl.state == "high", "battery high");
  CHECK(SL.calls == 0, "not asleep straight after ack");
  run(t_rep + 1000);
  CHECK(SL.calls == 1, "clean sleep after quiet period");
  run(t_rep + 3000);
  CHECK(SL.calls == 1, "sleep requested only once");

  std::printf("\n%s (%d failures)\n", fails ? "FAILED" : "ALL PASSED", fails);
  return fails ? 1 : 0;
}

int scenario2() {
  wifi::W w; api::A a; wifi::global_wifi_component = &w; api::global_api_server = &a;
  auto run = [&](uint32_t until) { while (g_now < until) { tick(); dump_tx(); g_now += 20; } };
  w.c = true;
  // garbage plus a corrupted frame before a valid time request
  for (uint8_t b : {0x00, 0xFF, 0x55, 0x12, 0x55, 0xAA, 0x00, 0x06, 0x00, 0x00, 0x99}) U.rx.push_back(b);
  for (auto b : frame(0x06, {})) U.rx.push_back(b);
  run(200);
  CHECK(tx_has({0x55,0xAA,0x00,0x06,0x00,0x08,0x01,0x1A,0x0B,0x02,0x10,0x09,0x05,0x01,0x54}),
        "time reply (Mon 2026-11-02 16:09:05, spec layout) after resync");
  for (auto b : frame(0x0B, {})) U.rx.push_back(b);
  run(300);
  CHECK(tx_has({0x55,0xAA,0x00,0x0B,0x00,0x02,0x01,0x50,0x5D}), "signal reply 80% matches spec example");
  // record-type report: time header + dp1 bool 1 with alarm value config 0 -> smoke OFF
  for (auto b : frame(0x08, {0x01,0x12,0x04,0x13,0x0D,0x03,0x1D, 0x01,0x04,0x00,0x01,0x01, 0x0B,0x05,0x00,0x01,0x02})) U.rx.push_back(b);
  run(800);
  CHECK(tx_has({0x55,0xAA,0x00,0x08,0x00,0x01,0x00,0x08}), "0x08 ack sent");
  CHECK(S_smoke.state == 0, "dp1=1 is smoke OFF");
  CHECK(S_fault.state == 1, "dp11=2 is fault ON");
  run(19000);
  CHECK(!tx_has({0x55,0xAA,0x00,0x02,0x00,0x01,0x04,0x06}), "no status 04 before api_wait_ms without HA");
  run(21000);
  CHECK(tx_has({0x55,0xAA,0x00,0x02,0x00,0x01,0x04,0x06}), "status 04 sent after api_wait_ms without HA");
  CHECK(SL.calls == 0, "no sleep while HA is not connected");
  // pairing request keeps module awake even after HA connects
  for (auto b : frame(0x04, {0x00})) U.rx.push_back(b);
  run(21100);
  CHECK(tx_has({0x55,0xAA,0x00,0x04,0x00,0x00,0x03}), "pairing ack matches spec 55 AA 00 04 00 00 03");
  a.c = true; run(30000);
  CHECK(SL.calls == 0, "stays awake in pairing mode");
  std::printf("\n%s (%d failures)\n", fails ? "FAILED" : "ALL PASSED", fails);
  return fails ? 1 : 0;
}
